```js
function validarCadastro(corpo) {
  // Verifica se corpo é um objeto válido
  if (corpo === null || typeof corpo !== 'object' || Array.isArray(corpo)) {
    return { status: 400, erros: ['email', 'senha', 'idade'] };
  }

  const erros = [];

  // Validação do email
  const email = corpo.email;
  if (typeof email !== 'string') {
    erros.push('email');
  } else {
    const partes = email.split('@');
    if (partes.length !== 2 || partes[0].length === 0 || partes[1].length === 0) {
      erros.push('email');
    }
  }

  // Validação da senha
  const senha = corpo.senha;
  if (typeof senha !== 'string' || senha.length < 8) {
    erros.push('senha');
  }

  // Validação da idade (opcional)
  const idade = corpo.idade;
  if (idade !== undefined) {
    if (!Number.isInteger(idade) || idade < 13 || idade > 120) {
      erros.push('idade');
    }
  }

  // Retorna resultado
  if (erros.length === 0) {
    return { status: 201, erros: [] };
  }

  return { status: 400, erros: erros };
}
