function validarCadastro(corpo) {
  const erros = [];

  // corpo deve ser um objeto não nulo
  if (!corpo || typeof corpo !== 'object' || Array.isArray(corpo)) {
    return { status: 400, erros: ['email', 'senha', 'idade'] };
  }

  // validação de email
  const email = corpo.email;
  const emailValido = typeof email === 'string' && /^[^@]+@[^@]+$/.test(email);
  if (!emailValido) erros.push('email');

  // validação de senha
  const senha = corpo.senha;
  const senhaValida = typeof senha === 'string' && senha.length >= 8;
  if (!senhaValida) erros.push('senha');

  // validação de idade (opcional)
  if ('idade' in corpo) {
    const idade = corpo.idade;
    const idadeValida = Number.isInteger(idade) && idade >= 13 && idade <= 120;
    if (!idadeValida) erros.push('idade');
  }

  return erros.length === 0
    ? { status: 201, erros: [] }
    : { status: 400, erros };
}
