function criarLimitador(max, janelaMs) {
  const mapa = new Map();

  return function permitir(chave, agora) {
    if (!mapa.has(chave)) {
      mapa.set(chave, []);
    }

    const timestamps = mapa.get(chave);
    const limite = agora - janelaMs;

    // Remove timestamps fora da janela
    while (timestamps.length > 0 && timestamps[0] < limite) {
      timestamps.shift();
    }

    if (timestamps.length < max) {
      timestamps.push(agora);
      return true;
    }

    return false;
  };
}
