function criarLimitador(max, janelaMs) {
  const dados = new Map();

  return function permitir(chave, agora) {
    if (max <= 0) return false;

    if (!dados.has(chave)) {
      dados.set(chave, []);
    }

    const timestamps = dados.get(chave);

    // Remove timestamps expirados (fora da janela)
    const limite = agora - janelaMs;
    while (timestamps.length > 0 && timestamps[0] < limite) {
      timestamps.shift();
    }

    // Verifica se ainda pode aceitar
    if (timestamps.length >= max) {
      return false;
    }

    // Registra o pedido permitido
    timestamps.push(agora);
    return true;
  }
}
